#include <cuda_runtime.h>

__global__ void batch_norm_stats_kernel(
    const float* input,
    float* mean,
    float* inv_std,
    int batch,
    int channels,
    int spatial,
    float eps) {
    int channel = blockIdx.x;
    int elements_per_channel = batch * spatial;
    double local_sum = 0.0;
    double local_square_sum = 0.0;

    for (int offset = threadIdx.x; offset < elements_per_channel; offset += blockDim.x) {
        int batch_index = offset / spatial;
        int spatial_index = offset - batch_index * spatial;
        int input_index = (batch_index * channels + channel) * spatial + spatial_index;
        double value = static_cast<double>(input[input_index]);
        local_sum += value;
        local_square_sum += value * value;
    }

    __shared__ double shared_sum[256];
    __shared__ double shared_square_sum[256];
    shared_sum[threadIdx.x] = local_sum;
    shared_square_sum[threadIdx.x] = local_square_sum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            shared_sum[threadIdx.x] += shared_sum[threadIdx.x + stride];
            shared_square_sum[threadIdx.x] += shared_square_sum[threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        double channel_mean = shared_sum[0] / elements_per_channel;
        double channel_variance =
            shared_square_sum[0] / elements_per_channel - channel_mean * channel_mean;
        channel_variance = channel_variance > 0.0 ? channel_variance : 0.0;
        mean[channel] = static_cast<float>(channel_mean);
        inv_std[channel] = rsqrtf(static_cast<float>(channel_variance) + eps);
    }
}

__global__ void batch_norm_kernel(
    float* output,
    const float* input,
    const float* mean,
    const float* inv_std,
    int channels,
    int spatial,
    int output_size) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    if (index < output_size) {
        int channel = (index / spatial) % channels;
        output[index] = (input[index] - mean[channel]) * inv_std[channel];
    }
}

extern "C" void batch_norm_launcher(
    float* output,
    const float* input,
    float* mean,
    float* inv_std,
    int batch,
    int channels,
    int spatial,
    int output_size,
    float eps,
    void* stream_handle) {
    auto stream = static_cast<cudaStream_t>(stream_handle);
    constexpr int threads = 256;
    batch_norm_stats_kernel<<<channels, threads, 0, stream>>>(
        input, mean, inv_std, batch, channels, spatial, eps);
    batch_norm_kernel<<<(output_size + threads - 1) / threads, threads, 0, stream>>>(
        output, input, mean, inv_std, channels, spatial, output_size);
}
